1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { PageHeader, timeAgo } from "@/components/ui/primitives";
4	import TeamManager, { type OrgView } from "@/components/customer/TeamManager";
5	
6	export const dynamic = "force-dynamic";
7	
8	function canAdminister(role: string): boolean {
9	  return role === "OWNER" || role === "ADMIN";
10	}
11	
12	export default async function TeamPage() {
13	  const user = await requireUser();
14	
15	  // Every org the user owns or belongs to (owner always has an OWNER membership).
16	  const memberships = await db.membership.findMany({
17	    where: { userId: user.id },
18	    orderBy: { createdAt: "asc" },
19	    include: {
20	      org: {
21	        include: {
22	          owner: { select: { id: true, name: true } },
23	          members: {
24	            orderBy: { createdAt: "asc" },
25	            include: { user: { select: { id: true, name: true, email: true } } },
26	          },
27	        },
28	      },
29	    },
30	  });
31	
32	  const orgs: OrgView[] = memberships.map((m) => {
33	    const org = m.org;
34	    return {
35	      id: org.id,
36	      name: org.name,
37	      createdAgo: timeAgo(org.createdAt),
38	      ownerName: org.owner.name,
39	      myRole: m.role,
40	      canAdminister: canAdminister(m.role),
41	      isOwner: org.ownerId === user.id,
42	      members: org.members.map((mem) => ({
43	        membershipId: mem.id,
44	        userId: mem.userId,
45	        name: mem.user.name,
46	        email: mem.user.email,
47	        role: mem.role,
48	        areas: Array.isArray(mem.areas) ? (mem.areas as string[]) : null,
49	        isOwner: mem.userId === org.ownerId,
50	        joinedAgo: timeAgo(mem.createdAt),
51	      })),
52	    };
53	  });
54	
55	  return (
56	    <div className="space-y-6">
57	      <PageHeader
58	        title="Team"
59	        sub="Create organizations and invite teammates to collaborate on a shared account."
60	      />
61	      <TeamManager orgs={orgs} />
62	    </div>
63	  );
64	}
