/**
 * Team invitations: consent tokens, plus who is entitled to see whom.
 *
 * WHY THIS MODULE NO LONGER EXPORTS `requireArea`
 * ----------------------------------------------
 * It used to export `requireArea(orgId, area)` — a page guard for "org-scoped
 * dashboard pages". There were none: `requireArea` had zero call sites in the
 * repo (AUDIT-24H rec. 47, QA-PRELAUNCH P1-19), `memberCanAccessHref` was
 * referenced only from its own docblock, and `Membership.areas` was write-only.
 * Meanwhile the Team UI rendered a checkbox per dashboard area and reported
 * "Access updated." So an owner who unticked everything except Invoices was
 * shown a restriction that no loader, action or route ever consulted. That is
 * the same defect class as the fake SSL certs and the migration that logged 4/4
 * with six domains dark, and it is the more dangerous shape of it: a security
 * control that reports success while enforcing nothing.
 *
 * Wiring it up for real would mean org-scoping every dashboard loader and every
 * server action that touches a server, domain, volume, invoice or ticket — none
 * of which live in this module's blast radius. A half-wired version (nav hidden,
 * loaders open) is strictly worse than none, because hiding a nav item looks
 * like enforcement. So the area system is deleted rather than faked, and this
 * module now carries the two things teams genuinely need in order to be safe.
 *
 * 1. INVITE TOKENS (consent). `inviteMember` used to create a Membership
 *    outright — the invitee never agreed to anything — and the team page then
 *    handed the inviter every co-member's `userId` and email. That is precisely
 *    the identity feed that made the unauthenticated 2FA oracle
 *    (`verifyTotpForUser`, QA-PRELAUNCH P0-2) targetable at a named account:
 *    type a victim's email, get back their internal id. Membership now requires
 *    the invitee to click Accept while signed in as the invited address.
 *
 * 2. `canAdministerOrg` — the single definition of "may administer membership",
 *    used both to authorise mutations and to decide whether a viewer is
 *    entitled to co-members' email addresses.
 *
 * Plain server-side module (no "use server"), so both the server actions and the
 * accept page can import these helpers. Nothing here is client-safe.
 */
import { createHash } from "node:crypto";
import { EncryptJWT, jwtDecrypt } from "jose";

/**
 * Invitation lifetime. Short on purpose: the token is the entire invitation
 * (see below), so expiry is the only thing that eventually retires a link the
 * sender regrets.
 */
export const INVITE_TTL_HOURS = 72;

/** What an invitation carries. `invitedBy` is re-checked at accept time. */
export type InviteClaims = {
  orgId: string;
  /** Lowercased email the invitation was addressed to. Binds the link to one person. */
  email: string;
  role: string;
  invitedBy: string;
};

/**
 * 256-bit key for the invite JWE, derived from AUTH_SECRET with an
 * invite-specific salt — the same derivation pattern as lib/terminal-token.ts.
 * The distinct salt means a session cookie can never be replayed as an
 * invitation (or vice-versa) even though both trace back to one secret.
 */
function inviteKey(): Uint8Array {
  const secret = process.env.AUTH_SECRET;
  if (!secret) throw new Error("AUTH_SECRET is not set — cannot issue team invitations");
  return new Uint8Array(createHash("sha256").update(`nxeon-org-invite:${secret}`).digest());
}

/**
 * Mint an invitation token.
 *
 * ENCRYPTED (JWE, A256GCM), not merely signed. A signed JWT's payload is
 * readable by anyone holding the link, and this payload contains the inviter's
 * `userId` — the exact value the 2FA oracle needed (P0-2). An invitation that
 * leaked an internal user id to whoever opened the email would reintroduce the
 * hole this change exists to close, so the token is opaque to its bearer.
 *
 * STATELESS by necessity: prisma/schema.prisma has no Invitation model and is
 * frozen for this change. The consequences are real and are stated plainly in
 * the UI rather than papered over — pending invitations cannot be listed, and
 * they cannot be revoked individually. What limits them instead:
 *   - they expire (INVITE_TTL_HOURS);
 *   - `acceptInvite` re-verifies that the inviter STILL holds OWNER/ADMIN in the
 *     org, so demoting or removing an admin voids their outstanding invitations;
 *   - they are bound to one email address, so a forwarded link is useless.
 * If pending-invite listing/revocation is wanted, that needs a schema field —
 * an `Invitation` model (orgId, email, role, invitedById, tokenHash, expiresAt,
 * acceptedAt, revokedAt) is the missing piece.
 */
export async function signInviteToken(claims: InviteClaims): Promise<string> {
  return new EncryptJWT({
    // `kind` is belt-and-braces on top of the salted key: any token that decrypts
    // but wasn't minted here is rejected rather than interpreted.
    kind: "org-invite",
    orgId: claims.orgId,
    email: claims.email,
    role: claims.role,
    invitedBy: claims.invitedBy,
  })
    .setProtectedHeader({ alg: "dir", enc: "A256GCM" })
    .setIssuedAt()
    .setExpirationTime(`${INVITE_TTL_HOURS}h`)
    .encrypt(inviteKey());
}

/**
 * Decrypt + validate an invitation token. Returns null for anything that isn't a
 * well-formed, unexpired invitation — tampered, truncated, expired, minted with
 * a different secret, or a token of some other kind. Never throws, so callers
 * can render one honest "invalid or expired" message without leaking which of
 * those it was.
 */
export async function verifyInviteToken(token: string): Promise<InviteClaims | null> {
  if (!token) return null;
  try {
    const { payload } = await jwtDecrypt(token, inviteKey());
    if (payload.kind !== "org-invite") return null;
    const { orgId, email, role, invitedBy } = payload as Record<string, unknown>;
    if (
      typeof orgId !== "string" ||
      typeof email !== "string" ||
      typeof role !== "string" ||
      typeof invitedBy !== "string" ||
      !orgId ||
      !email ||
      !role ||
      !invitedBy
    ) {
      return null;
    }
    return { orgId, email: email.toLowerCase(), role, invitedBy };
  } catch {
    return null;
  }
}

/**
 * Roles that may administer membership (invite / change roles / remove) — and,
 * because the two questions have the same answer, the only viewers entitled to
 * see co-members' email addresses. A rank-and-file member gets the roster's
 * names; harvesting a list of addresses out of an org you were added to is how
 * the identity leak above was monetised.
 */
export function canAdministerOrg(role: string): boolean {
  return role === "OWNER" || role === "ADMIN";
}

"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import { checkRateLimit } from "./rate-limit";
import { canAdministerOrg, signInviteToken, verifyInviteToken, INVITE_TTL_HOURS } from "./team-guard";

/**
 * Teams / Organizations — shared-account server actions.
 *
 * An Organization has one owner (User "OrgOwner") plus a set of Memberships.
 * Every actor is verified to hold a Membership of the required role in the
 * target org before any mutation runs, so a hand-crafted request can't touch
 * an org the caller doesn't belong to.
 *
 * WHAT A MEMBERSHIP ACTUALLY GRANTS (be precise — this used to be overstated):
 * visibility of the org roster, and, for OWNER/ADMIN, the right to invite,
 * re-role and remove members. It grants NOTHING ELSE. Servers, domains,
 * volumes, game servers, billing and invoices all remain scoped to the account
 * that owns them; no loader or action anywhere joins Membership to a resource.
 * The per-member "dashboard areas" control that used to sit on this page has
 * been removed rather than left in place: `Membership.areas` was written, echoed
 * back as saved, and read by nothing, so an owner who restricted a member to
 * Invoices was shown a restriction that did not exist. See lib/team-guard.ts for
 * why enforcing it for real is out of this change's reach, and the note rendered
 * in components/customer/TeamManager.tsx for what the customer is now told.
 *
 * CONSENT: `inviteMember` emails an invitation; only `acceptInvite`, run by the
 * invitee, creates a Membership. Nothing here can add a person to an org they
 * did not agree to join — see lib/team-guard.ts for the full rationale (it is
 * what fed the 2FA oracle, QA-PRELAUNCH P0-2).
 *
 * STILL OUT OF SCOPE: shared billing (org wallet / invoices) and members
 * inheriting access to shared servers. Deliberately absent, not half-built.
 */

const ROLES = ["OWNER", "ADMIN", "MEMBER", "BILLING"] as const;
type OrgRole = (typeof ROLES)[number];

function isRole(v: string): v is OrgRole {
  return (ROLES as readonly string[]).includes(v);
}

/** Load the actor's membership in an org, or null if they aren't a member. */
async function actorMembership(orgId: string, userId: string) {
  if (!orgId) return null;
  return db.membership.findUnique({
    where: { orgId_userId: { orgId, userId } },
  });
}

/**
 * Create an organization owned by the current user, plus an OWNER membership
 * for the creator. Consumed via `useActionState`.
 */
export async function createOrg(
  _prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 2 || name.length > 60) {
    return { error: "Organization name must be 2–60 characters." };
  }

  await db.organization.create({
    data: {
      name,
      ownerId: user.id,
      members: {
        create: { userId: user.id, role: "OWNER" },
      },
    },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "org.created", detail: name },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Email an invitation. Only OWNER/ADMIN of the org may invite. **No Membership
 * is created here** — the invitee creates it themselves via `acceptInvite`.
 *
 * Deliberately does NOT look the email up in the User table. The old version
 * did, and that single query produced two leaks from one action any signed-in
 * customer can call: it answered "does an account exist with this address?"
 * (enumeration oracle), and on a hit it created a Membership whose row then
 * exposed the invitee's internal `userId` on the team page — the input the
 * unauthenticated 2FA oracle needed (QA-PRELAUNCH P0-2). We send the mail and
 * learn nothing: the same response comes back whether or not the address has an
 * account, and the sender finds out only if the person chooses to accept.
 */
export async function inviteMember(
  orgId: string,
  email: string,
  role: string,
): Promise<{ error?: string; ok?: boolean; message?: string }> {
  const user = await requireUser();
  const invitedEmail = String(email ?? "").trim().toLowerCase();
  if (!invitedEmail || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(invitedEmail)) {
    return { error: "Enter a valid email address." };
  }
  const wantRole = String(role ?? "MEMBER").toUpperCase();
  if (!isRole(wantRole) || wantRole === "OWNER") {
    // OWNER is assigned only at creation / ownership transfer, never via invite.
    return { error: "Choose a role of ADMIN, MEMBER or BILLING." };
  }

  const actor = await actorMembership(orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to invite members to this organization." };
  }

  const org = await db.organization.findUnique({ where: { id: orgId }, select: { name: true } });
  if (!org) return { error: "Organization not found." };

  if (invitedEmail === user.email.toLowerCase()) {
    return { error: "You're already a member of this organization." };
  }

  // Throttle per inviter. This action sends Nxeon-branded mail to an arbitrary
  // address chosen by the caller, so without a cap it is a spam relay and a way
  // to bury someone in invitations. Same shape as the login / password-reset
  // throttles (lib/rate-limit.ts).
  const rl = checkRateLimit(`org-invite:${user.id}`, { max: 10, windowMs: 60 * 60 * 1000 });
  if (!rl.ok) {
    return {
      error: `Too many invitations sent recently. Try again in ${Math.ceil(rl.retryAfterSec / 60)} minute(s).`,
    };
  }

  const token = await signInviteToken({
    orgId,
    email: invitedEmail,
    role: wantRole,
    invitedBy: user.id,
  });
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  const acceptUrl = `${base}/dashboard/team/accept?token=${encodeURIComponent(token)}`;

  const { sendMail, emails } = await import("./mailer");
  const tpl = emails.teamInvite({
    inviterName: user.name,
    teamName: org.name,
    acceptUrl,
  });
  const sent = await sendMail({ to: invitedEmail, subject: tpl.subject, html: tpl.html });
  if (!sent) {
    // Report the failure instead of claiming the invitation went out. `sendMail`
    // returns false (and logs to EmailLog) when SMTP is unconfigured or the send
    // throws; a cheerful "Invitation sent." over a dropped email is exactly the
    // confidently-wrong surface this codebase keeps getting bitten by.
    return { error: "We couldn't send that invitation email. Check mail settings and try again." };
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "org.invite_sent",
      detail: `${invitedEmail} → ${wantRole}`,
    },
  });
  return {
    ok: true,
    message: `Invitation emailed to ${invitedEmail}. They join the organization when they accept it — the link expires in ${INVITE_TTL_HOURS} hours.`,
  };
}

/**
 * Accept an invitation. This is the ONLY path that creates a Membership for
 * someone other than an org's creator, and it runs as the invitee — clicking
 * Accept while signed in as the invited address *is* the consent.
 *
 * Must be triggered by a deliberate click, never on page load: a mutation that
 * fires when the emailed URL is merely opened (or prefetched) would join people
 * to organizations without their agreement all over again.
 *
 * Re-checks at redemption time, because the token carries no server-side state:
 * the org still exists, the inviter still administers it, the role is still
 * sane, and the token's address matches the signed-in account.
 */
export async function acceptInvite(
  token: string,
): Promise<{ error?: string; ok?: boolean; orgName?: string; alreadyMember?: boolean }> {
  const user = await requireUser();

  const claims = await verifyInviteToken(String(token ?? ""));
  if (!claims) {
    return {
      error: "This invitation link is invalid or has expired. Ask the organization owner to send a new one.",
    };
  }

  // Bound to one address, so a forwarded link can't be redeemed by the recipient.
  if (claims.email !== user.email.trim().toLowerCase()) {
    return {
      error: "This invitation was sent to a different email address. Sign in as that account to accept it.",
    };
  }

  if (!isRole(claims.role) || claims.role === "OWNER") {
    return { error: "This invitation carries an invalid role and can't be accepted." };
  }

  const org = await db.organization.findUnique({
    where: { id: claims.orgId },
    select: { id: true, name: true },
  });
  if (!org) return { error: "That organization no longer exists." };

  // Revocation, given there is no invitation row to delete: an outstanding
  // invitation dies the moment its sender loses the right to have sent it.
  const inviter = await actorMembership(org.id, claims.invitedBy);
  if (!inviter || !canAdministerOrg(inviter.role)) {
    return {
      error: "Whoever invited you no longer administers this organization, so the invitation is no longer valid.",
    };
  }

  const existing = await actorMembership(org.id, user.id);
  if (existing) {
    return { ok: true, orgName: org.name, alreadyMember: true };
  }

  await db.membership.create({
    data: { orgId: org.id, userId: user.id, role: claims.role },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "org.invite_accepted",
      detail: `${org.name} → ${claims.role}`,
    },
  });
  revalidatePath("/dashboard/team");
  return { ok: true, orgName: org.name };
}

/**
 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
 * pinned to OWNER and cannot be downgraded here.
 *
 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
 * back. The org is derived from the membership rather than trusted from the
 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
 */
export async function updateMemberRole(
  membershipId: string,
  role: string,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const wantRole = String(role ?? "").toUpperCase();
  if (!isRole(wantRole) || wantRole === "OWNER") {
    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
  }

  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
  if (!target) return { error: "That person isn't a member of this organization." };

  const actor = await actorMembership(target.orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to change roles in this organization." };
  }

  const org = await db.organization.findUnique({
    where: { id: target.orgId },
    select: { ownerId: true },
  });
  if (!org) return { error: "Organization not found." };
  if (target.userId === org.ownerId || target.role === "OWNER") {
    return { error: "The organization owner's role can't be changed." };
  }

  await db.membership.update({
    where: { id: target.id },
    data: { role: wantRole },
  });
  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "org.member_role_changed",
      detail: `${target.userId} → ${wantRole}`,
    },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Remove a member. Only OWNER/ADMIN act; the owner can never be removed.
 * Keyed by `membershipId` for the same reason as `updateMemberRole`.
 */
export async function removeMember(
  membershipId: string,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
  if (!target) return { error: "That person isn't a member of this organization." };

  const actor = await actorMembership(target.orgId, user.id);
  if (!actor || !canAdministerOrg(actor.role)) {
    return { error: "You don't have permission to remove members from this organization." };
  }

  const org = await db.organization.findUnique({
    where: { id: target.orgId },
    select: { ownerId: true },
  });
  if (!org) return { error: "Organization not found." };
  if (target.userId === org.ownerId || target.role === "OWNER") {
    return { error: "The organization owner can't be removed." };
  }

  await db.membership.delete({ where: { id: target.id } });
  await db.auditLog.create({
    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

/**
 * Leave an organization. The owner can't leave their own org (they'd have to
 * transfer ownership first — a follow-up), everyone else may.
 */
export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();

  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
  if (!org) return { error: "Organization not found." };
  if (org.ownerId === user.id) {
    return { error: "As the owner you can't leave — transfer ownership or delete the organization instead." };
  }

  const membership = await actorMembership(orgId, user.id);
  if (!membership) return { error: "You're not a member of this organization." };

  await db.membership.deleteMany({ where: { orgId, userId: user.id } });
  await db.auditLog.create({
    data: { userId: user.id, action: "org.left", detail: orgId },
  });
  revalidatePath("/dashboard/team");
  return { ok: true };
}

import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { canAdministerOrg } from "@/lib/team-guard";
import { PageHeader, timeAgo } from "@/components/ui/primitives";
import TeamManager, { type OrgView } from "@/components/customer/TeamManager";

export const dynamic = "force-dynamic";

export default async function TeamPage() {
  const user = await requireUser();

  // Every org the user owns or belongs to (owner always has an OWNER membership).
  const memberships = await db.membership.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "asc" },
    include: {
      org: {
        include: {
          owner: { select: { id: true, name: true } },
          members: {
            orderBy: { createdAt: "asc" },
            include: { user: { select: { id: true, name: true, email: true } } },
          },
        },
      },
    },
  });

  const orgs: OrgView[] = memberships.map((m) => {
    const org = m.org;
    const iAdminister = canAdministerOrg(m.role);
    return {
      id: org.id,
      name: org.name,
      createdAgo: timeAgo(org.createdAt),
      ownerName: org.owner.name,
      myRole: m.role,
      canAdminister: iAdminister,
      isOwner: org.ownerId === user.id,
      members: org.members.map((mem) => {
        const isSelf = mem.userId === user.id;
        return {
          // The client is never given a co-member's `userId`. Combined with an
          // email address that was the whole attack: `verifyTotpForUser`
          // (QA-PRELAUNCH P0-2) took an arbitrary userId with no auth and no
          // rate limit, and this page used to hand one over for every member of
          // every org the viewer was in — an org they could have been added to
          // without consenting. The oracle is fixed; the ids still have no
          // business crossing to the browser, so role/remove are keyed by
          // membership id instead (see lib/actions-teams.ts).
          membershipId: iAdminister ? mem.id : null,
          name: mem.user.name,
          // Addresses go only to viewers entitled to them: someone who can
          // actually administer membership, plus your own row. A rank-and-file
          // MEMBER sees names, not a harvestable address list.
          email: iAdminister || isSelf ? mem.user.email : null,
          role: mem.role,
          isOwner: mem.userId === org.ownerId,
          isSelf,
          joinedAgo: timeAgo(mem.createdAt),
        };
      }),
    };
  });

  return (
    <div className="space-y-6">
      <PageHeader
        title="Team"
        sub="Create organizations and invite teammates to your shared roster."
      />
      <TeamManager orgs={orgs} />
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { canAdministerOrg, verifyInviteToken } from "@/lib/team-guard";
import { PageHeader } from "@/components/ui/primitives";
import TeamInviteAccept from "@/components/customer/TeamInviteAccept";

export const dynamic = "force-dynamic";

/**
 * Landing page for the "Accept invitation" link in the team-invite email.
 *
 * This page only DESCRIBES the invitation — it never joins anyone. Joining
 * happens in `acceptInvite`, behind a button the invitee presses. That split is
 * the point of the whole change: an org membership must be an act by the
 * invitee, not a side effect of an email link being opened (or prefetched by a
 * mail client). Previously `inviteMember` created the membership on the
 * inviter's click alone.
 *
 * Signed-out visitors are bounced to /login by the dashboard layout. Someone
 * without an account yet registers first and then re-opens the emailed link;
 * the link stays valid for its full lifetime, so nothing is lost.
 */
export default async function AcceptInvitePage({
  searchParams,
}: {
  searchParams: Promise<{ token?: string }>;
}) {
  const user = await requireUser();
  const { token } = await searchParams;

  const claims = await verifyInviteToken(String(token ?? ""));

  // Everything below decides only what to SHOW. Each check is repeated
  // server-side in `acceptInvite`, because a page render is not a permission.
  let problem: string | null = null;
  let orgName: string | null = null;
  let inviterName: string | null = null;

  if (!claims) {
    problem = "This invitation link is invalid or has expired. Ask the organization owner to send a new one.";
  } else if (claims.email !== user.email.trim().toLowerCase()) {
    // Don't name the org here: the signed-in account isn't the invitee, so it
    // isn't entitled to know which organization the link belongs to.
    problem = `This invitation was sent to a different email address. You're signed in as ${user.email} — sign in as the invited account to accept it.`;
  } else {
    const org = await db.organization.findUnique({
      where: { id: claims.orgId },
      select: { id: true, name: true },
    });
    const inviter = org
      ? await db.membership.findUnique({
          where: { orgId_userId: { orgId: org.id, userId: claims.invitedBy } },
          include: { user: { select: { name: true } } },
        })
      : null;
    if (!org) {
      problem = "That organization no longer exists.";
    } else if (!inviter || !canAdministerOrg(inviter.role)) {
      problem = "Whoever invited you no longer administers this organization, so the invitation is no longer valid.";
    } else {
      orgName = org.name;
      inviterName = inviter.user.name;
    }
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Team invitation" sub="Review the invitation before you join." />
      {problem || !claims || !orgName ? (
        <div className="card space-y-3">
          <p className="text-sm text-red-400">{problem ?? "This invitation can't be opened."}</p>
          <Link href="/dashboard/team" className="btn-ghost inline-flex px-3 py-1 text-xs">
            Back to Team
          </Link>
        </div>
      ) : (
        <TeamInviteAccept
          token={String(token)}
          orgName={orgName}
          inviterName={inviterName ?? "An organization admin"}
          role={claims.role}
        />
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import { acceptInvite } from "@/lib/actions-teams";

/**
 * The consent step of a team invitation. Renders what is being joined and waits
 * for a deliberate click — `acceptInvite` is the only thing in the codebase that
 * can add someone to an organization, and it runs as the invitee. Nothing fires
 * on mount: an invitation that redeemed itself when the emailed link loaded
 * would be no more consensual than the old behaviour, where an org admin could
 * add any existing account by typing its address.
 *
 * The capability list is deliberately unglamorous. It is what a membership
 * currently does, and no more — the previous UI implied per-area access control
 * over the owner's servers and billing that was never enforced anywhere.
 */
export default function TeamInviteAccept({
  token,
  orgName,
  inviterName,
  role,
}: {
  token: string;
  orgName: string;
  inviterName: string;
  role: string;
}) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  const [joined, setJoined] = useState(false);

  function accept() {
    setErr(null);
    start(async () => {
      const res = await acceptInvite(token);
      if (res.error) setErr(res.error);
      else if (res.ok) setJoined(true);
    });
  }

  if (joined) {
    return (
      <div className="card space-y-3">
        <p className="text-sm text-emerald-400">You've joined {orgName}.</p>
        <Link href="/dashboard/team" className="btn-primary inline-flex px-3 py-1 text-xs">
          Open Team
        </Link>
      </div>
    );
  }

  return (
    <div className="card space-y-4">
      <div>
        <h2 className="flex flex-wrap items-center gap-2 font-semibold">
          Join {orgName}
          <Badge tone="slate">{role.toLowerCase()}</Badge>
        </h2>
        <p className="mt-1 text-sm text-slate-400">
          {inviterName} invited you to join <span className="text-slate-200">{orgName}</span> as{" "}
          {role.toLowerCase()}.
        </p>
      </div>

      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-3 text-xs text-slate-400">
        <p className="mb-1 font-medium text-slate-300">What joining does</p>
        <ul className="list-disc space-y-1 pl-4">
          <li>You appear on this organization's member list, and can see who else is on it.</li>
          {role === "ADMIN" && <li>As an admin you can invite, re-role and remove other members.</li>}
          <li>
            It does <span className="text-slate-200">not</span> share resources: servers, domains,
            volumes, billing and invoices stay with the account that owns them. Yours stay yours.
          </li>
          <li>You can leave at any time from the Team page.</li>
        </ul>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <button className="btn-primary" disabled={pending} onClick={accept}>
          {pending ? "Joining…" : "Accept invitation"}
        </button>
        <Link href="/dashboard" className="btn-ghost px-3 py-1 text-xs">
          Not now
        </Link>
        <span className="text-[11px] text-slate-500">
          There's nothing to decline — ignore the link and it expires on its own.
        </span>
      </div>
      {err && <p className="text-sm text-red-400">{err}</p>}
    </div>
  );
}

"use client";

import { useActionState, useState, useTransition } from "react";
import { Badge } from "@/components/ui/primitives";
import {
  createOrg,
  inviteMember,
  updateMemberRole,
  removeMember,
  leaveOrg,
} from "@/lib/actions-teams";

/**
 * Team management UI.
 *
 * Two things were removed here rather than left looking functional:
 *
 * 1. The per-member "Dashboard access" checkboxes. They wrote
 *    `Membership.areas`, said "Access updated.", and were read by nothing — an
 *    owner who restricted a member to Invoices got a UI asserting a restriction
 *    that no loader or action enforced (AUDIT-24H rec. 47, QA-PRELAUNCH P1-19).
 *    Since membership grants no resource access at all, there was nothing to
 *    restrict; the honest replacement is the capability note below.
 *
 * 2. Co-members' user ids. The page loader no longer sends them (see
 *    app/dashboard/team/page.tsx), and email addresses arrive only for viewers
 *    entitled to them, so `email` here is nullable by design.
 *
 * "Add member" is now genuinely an invitation: it emails a link the invitee has
 * to accept. Members therefore appear in this list on their own action, not the
 * inviter's.
 */

export type OrgMemberView = {
  /** Present only when the viewer may administer this org; null otherwise. */
  membershipId: string | null;
  name: string;
  /** Null when the viewer isn't entitled to this member's address. */
  email: string | null;
  role: string;
  isOwner: boolean;
  isSelf: boolean;
  joinedAgo: string;
};

export type OrgView = {
  id: string;
  name: string;
  createdAgo: string;
  ownerName: string;
  myRole: string;
  canAdminister: boolean;
  isOwner: boolean;
  members: OrgMemberView[];
};

const ASSIGNABLE_ROLES = ["ADMIN", "MEMBER", "BILLING"] as const;

function roleTone(role: string): "brand" | "green" | "amber" | "slate" {
  if (role === "OWNER") return "brand";
  if (role === "ADMIN") return "green";
  if (role === "BILLING") return "amber";
  return "slate";
}

/* ---------------- Create org ---------------- */

function CreateOrgForm() {
  const [state, action, pending] = useActionState(createOrg, {} as { error?: string; ok?: boolean });
  return (
    <form action={action} className="flex flex-wrap items-end gap-3">
      <div>
        <label className="label">Organization name</label>
        <input
          className="input w-64"
          name="name"
          required
          minLength={2}
          maxLength={60}
          placeholder="Acme Inc."
        />
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Creating…" : "Create organization"}
      </button>
      {state?.error && <p className="w-full text-sm text-red-400">{state.error}</p>}
      {state?.ok && <p className="w-full text-sm text-emerald-400">Organization created.</p>}
    </form>
  );
}

/* ---------------- Invite ---------------- */

function InviteForm({ orgId }: { orgId: string }) {
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<string>("MEMBER");
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ tone: "error" | "info" | "ok"; text: string } | null>(null);

  function submit(e: React.FormEvent) {
    e.preventDefault();
    setMsg(null);
    start(async () => {
      const res = await inviteMember(orgId, email, role);
      if (res.error) setMsg({ tone: "error", text: res.error });
      else if (res.ok) {
        setMsg({ tone: "ok", text: res.message ?? "Invitation sent." });
        setEmail("");
      } else if (res.message) setMsg({ tone: "info", text: res.message });
    });
  }

  return (
    <form onSubmit={submit} className="flex flex-wrap items-end gap-3">
      <div>
        <label className="label">Invite by email</label>
        <input
          className="input w-64"
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
          placeholder="teammate@example.com"
        />
      </div>
      <div>
        <label className="label">Role</label>
        <select className="input w-36" value={role} onChange={(e) => setRole(e.target.value)}>
          {ASSIGNABLE_ROLES.map((r) => (
            <option key={r} value={r}>
              {r.charAt(0) + r.slice(1).toLowerCase()}
            </option>
          ))}
        </select>
      </div>
      <button className="btn-primary" disabled={pending || !email}>
        {pending ? "Sending…" : "Send invitation"}
      </button>
      {/* Say what the button does. It emails a link; the person joins when they
          accept it. Pending invitations aren't stored server-side, so this list
          can't show them — better to admit that than to imply a queue exists. */}
      <p className="w-full text-[11px] text-slate-500">
        We email an invitation link. They appear below once they accept it — pending invitations
        aren't tracked, so re-send the invite if it expires.
      </p>
      {msg && (
        <p
          className={`w-full text-sm ${
            msg.tone === "error"
              ? "text-red-400"
              : msg.tone === "ok"
                ? "text-emerald-400"
                : "text-amber-300"
          }`}
        >
          {msg.text}
        </p>
      )}
    </form>
  );
}

/* ---------------- Row controls ---------------- */

function RoleSelect({ membershipId, role }: { membershipId: string; role: string }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-start">
      <select
        className="input py-1 text-xs"
        defaultValue={role}
        disabled={pending}
        onChange={(e) => {
          const next = e.target.value;
          setErr(null);
          start(async () => {
            const res = await updateMemberRole(membershipId, next);
            if (res.error) setErr(res.error);
          });
        }}
      >
        {ASSIGNABLE_ROLES.map((r) => (
          <option key={r} value={r}>
            {r.charAt(0) + r.slice(1).toLowerCase()}
          </option>
        ))}
      </select>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </div>
  );
}

function RemoveButton({ membershipId, name }: { membershipId: string; name: string }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-end">
      <button
        className="btn-danger px-3 py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!window.confirm(`Remove ${name} from this organization?`)) return;
          setErr(null);
          start(async () => {
            const res = await removeMember(membershipId);
            if (res.error) setErr(res.error);
          });
        }}
      >
        {pending ? "…" : "Remove"}
      </button>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </div>
  );
}

function LeaveButton({ orgId }: { orgId: string }) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-end">
      <button
        className="btn-ghost px-3 py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!window.confirm("Leave this organization?")) return;
          setErr(null);
          start(async () => {
            const res = await leaveOrg(orgId);
            if (res.error) setErr(res.error);
          });
        }}
      >
        {pending ? "…" : "Leave organization"}
      </button>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </div>
  );
}

/* ---------------- Org card ---------------- */

function OrgCard({ org }: { org: OrgView }) {
  return (
    <div className="card space-y-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h3 className="flex items-center gap-2 font-semibold">
            {org.name}
            <Badge tone={roleTone(org.myRole)}>{org.myRole.toLowerCase()}</Badge>
          </h3>
          <p className="mt-1 text-xs text-slate-400">
            Owned by {org.ownerName} · {org.members.length} member
            {org.members.length === 1 ? "" : "s"} · created {org.createdAgo}
          </p>
        </div>
        {!org.isOwner && <LeaveButton orgId={org.id} />}
      </div>

      <div className="table-wrap overflow-x-auto">
        <table className="table-shell min-w-[560px]">
          <thead>
            <tr>
              <th>Member</th>
              <th>Role</th>
              <th>Joined</th>
              {org.canAdminister && <th className="text-right">Actions</th>}
            </tr>
          </thead>
          <tbody>
            {org.members.map((m, i) => (
              <tr key={m.membershipId ?? `${org.id}-${i}`}>
                <td>
                  <span className="font-medium">{m.name}</span>
                  {m.isSelf && <span className="ml-2 text-xs text-slate-500">you</span>}
                  {/* Absent, not blanked out: a viewer who isn't entitled to a
                      co-member's address simply isn't shown a slot for one. */}
                  {m.email && <span className="ml-2 text-xs text-slate-500">{m.email}</span>}
                </td>
                <td>
                  {org.canAdminister && !m.isOwner && m.membershipId ? (
                    <RoleSelect membershipId={m.membershipId} role={m.role} />
                  ) : (
                    <Badge tone={roleTone(m.role)}>{m.role.toLowerCase()}</Badge>
                  )}
                </td>
                <td className="text-xs text-slate-400">{m.joinedAgo}</td>
                {org.canAdminister && (
                  <td className="text-right">
                    {m.isOwner || !m.membershipId ? (
                      <span className="text-xs text-slate-500">{m.isOwner ? "owner" : "—"}</span>
                    ) : (
                      <RemoveButton membershipId={m.membershipId} name={m.name} />
                    )}
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {org.canAdminister && (
        <div className="border-t border-white/[0.06] pt-4">
          <InviteForm orgId={org.id} />
        </div>
      )}
    </div>
  );
}

/* ---------------- What membership actually grants ---------------- */

/**
 * Stated up front, because the previous version of this page implied far more.
 * An owner reading it should come away with no illusion that adding someone to
 * an organization restricts — or grants — anything on their servers or billing.
 */
function CapabilityNote() {
  return (
    <div className="card">
      <h2 className="mb-1 font-semibold">What organization membership grants</h2>
      <ul className="list-disc space-y-1 pl-5 text-sm text-slate-400">
        <li>Members see the organization's roster; owners and admins see member email addresses.</li>
        <li>Owners and admins can invite, re-role and remove members.</li>
        <li>
          Nothing else is shared yet. Servers, domains, volumes, game servers, billing and invoices
          stay with the account that owns them, so membership gives no access to another member's
          resources and there is nothing per-member to restrict.
        </li>
        <li>Anyone but the owner can leave an organization at any time.</li>
      </ul>
    </div>
  );
}

/* ---------------- Top-level ---------------- */

export default function TeamManager({ orgs }: { orgs: OrgView[] }) {
  return (
    <div className="space-y-6">
      <div className="card">
        <h2 className="mb-1 font-semibold">Create an organization</h2>
        <p className="mb-4 text-sm text-slate-400">
          Group teammates under a shared roster. You become its owner.
        </p>
        <CreateOrgForm />
      </div>

      <CapabilityNote />

      {orgs.length === 0 ? (
        <div className="card text-sm text-slate-400">
          You don't belong to any organizations yet. Create one above to start inviting teammates.
        </div>
      ) : (
        orgs.map((org) => <OrgCard key={org.id} org={org} />)
      )}
    </div>
  );
}

